<script setup lang="ts">
import type { PreviewState } from '../useStudio';
defineProps<{duration:number;start:number;end:number;preview:PreviewState}>();
const emit=defineEmits<{updateStart:[n:number];updateEnd:[n:number];analyze:[];prepare:[];togglePreview:[];toggleLoop:[]}>();
// 滑块连续拖动期间（@input）只做失效处理（由父级停止旧播放）；拖动结束（@change）再准备新试听，
// 避免每个拖动刻度都触发一次异步准备。
</script>
<template><section class="stage-card"><span class="kicker">02 / TRIM THE MOMENT</span><h2>留下最有表情的十秒</h2><div class="timeline"><div class="timeline-fill" :style="{left:`${start/duration*100||0}%`,right:`${100-(end/duration*100||0)}%`}"></div></div><div class="range-pair"><label>起点 {{ start.toFixed(1) }}s<input type="range" min="0" :max="Math.max(0,duration-.1)" step=".1" :value="start" @input="emit('updateStart',Number(($event.target as HTMLInputElement).value))" @change="emit('prepare')"></label><label>终点 {{ end.toFixed(1) }}s<input type="range" :min="Math.min(duration,start+.1)" :max="duration" step=".1" :value="end" @input="emit('updateEnd',Number(($event.target as HTMLInputElement).value))" @change="emit('prepare')"></label></div><div class="preview-bar" data-testid="preview-bar"><button data-testid="preview-toggle" class="acid-button secondary" type="button" @click="emit('togglePreview')">{{ preview.playing && !preview.paused ? '⏸ 暂停试听' : preview.paused ? '▶ 继续试听' : '▶ 试听片段' }}</button><button data-testid="preview-loop" class="loop-button" :class="{active:preview.looping}" type="button" @click="emit('toggleLoop')" :aria-pressed="preview.looping">{{ preview.looping ? '🔁 循环中' : '🔁 循环' }}</button><span class="preview-meta">{{ preview.error ? preview.error : `试听时长 ${preview.duration.toFixed(1)}s，与分析、保存的声音一致` }}</span></div><button data-testid="analyze" class="acid-button" type="button" @click="emit('analyze')">分析这段声音 →</button></section></template>
